-- AD9 (ADMIN DESK SQL, step 9, 23 Nov 2026 PKT): RUNBOOK LIBRARY, versioned, approved by the Chairman. Phase 1k (D5b-1, D5b-3). List: docs/claude/admin-desk/D5B-RUNBOOKS-LIST-23NOV.md (R1..R12).
-- GENERATED by tools/gen-ad9.py from tools/AD9.template.sql + RUNBOOK-LIBRARY-DRAFT-22NOV.md (edit the template or the draft, never this file by hand).
-- BUILT ON (SCHEMA-FIRST LAW, read in full): AD1 (fadm_owner role owner/agent, fadm_ledger hash chain, forced RLS + p_installer policy pattern), AD2 (closed ledger kind list), AD8 (SECURITY DEFINER door pattern, selftest with P0AH9-style rollback).
-- TECHNOLOGY: PostgreSQL 16 forced RLS, append-only version rows with their OWN SHA-256 hash chain (like AD4b), semantic version per runbook, a no-promise word list enforced by a CHECK (the same list the commit gate and the screen use),
--   SECURITY DEFINER doors only (desk_app has NO right on any table), every approval and validation in the main hash-chained ledger, a selftest that rolls back.
-- ADVANCE (web research 23 Nov 2026): (R1) exactly six parts, enforced by CHECK; (R2) owner = a ROLE: only role 'owner' (the Chairman) can approve or validate; (R3) semver + changelog, a version row is never edited and its number must rise;
--   (R4) two dates: created (last updated) and last validated, and a 90-day stale flag computed in the database; (R5) approval is a separate append-only event, so a runbook is "Draft" until an owner approves that exact version;
--   (R7) no-promise CHECK on the say-text with ONE whitelisted policy sentence; (R9) steps are a closed JSON array of 1..12 short sentences.
-- RULES: Desk tables only (fadm_*), idempotent, ONE transaction, no superuser. No money, no customer data: runbooks are staff instructions.
-- ==============================================================================================================================
BEGIN;
INSERT INTO desk.fadm_ledger_kind (kind, severity, note) VALUES
  ('ad9.selftest','info','AD9'),('runbook.version_added','notice','a new runbook version was added by an owner'),
  ('runbook.approved','notice','the Chairman approved a runbook version'),('runbook.validated','info','an owner validated a runbook version against real work')
ON CONFLICT (kind) DO NOTHING;

-- 1) the no-promise rule, in the database (R7). ONE whitelisted sentence (the published billing policy line) is removed first; then any banned word fails.
CREATE OR REPLACE FUNCTION desk.fadm_runbook_clean(t text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = pg_catalog AS $f$
  SELECT t IS NOT NULL AND replace(t, 'Our published billing policy says payments are not refunded or credited once the service has been used. You can read it on the Billing Policy page.', '')  -- no-money-gate-ok
    !~* '(promise|guarantee|definitely|for sure|100 percent|will be fixed|will be restored|refund|credit|compensation|discount|\mfree\M|i will make sure|within [0-9]+ *(hours?|minutes?|days?|mins?))' $f$;  -- no-money-gate-ok

-- 2) the runbooks and their versions
CREATE TABLE IF NOT EXISTS desk.fadm_runbook (
  key   text PRIMARY KEY CHECK (key ~ '^R[0-9]{1,2}$'),
  title text NOT NULL CHECK (length(title) BETWEEN 3 AND 80),
  sort  integer NOT NULL CHECK (sort BETWEEN 1 AND 99)
);
CREATE TABLE IF NOT EXISTS desk.fadm_runbook_version (
  id          bigserial PRIMARY KEY,
  runbook_key text NOT NULL REFERENCES desk.fadm_runbook(key),
  major integer NOT NULL CHECK (major >= 0), minor integer NOT NULL CHECK (minor >= 0), patch integer NOT NULL CHECK (patch >= 0),
  parts       jsonb NOT NULL,
  steps       jsonb NOT NULL,
  say_text    text  NOT NULL CHECK (length(say_text) BETWEEN 10 AND 600),
  changelog   text  NOT NULL CHECK (length(changelog) BETWEEN 3 AND 400),
  changed_by  uuid  REFERENCES desk.fadm_owner(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  prev_hash   bytea NOT NULL DEFAULT sha256('x'::bytea),
  hash        bytea NOT NULL DEFAULT sha256('x'::bytea),
  UNIQUE (runbook_key, major, minor, patch),
  -- R1: exactly the six parts, every one a non-empty string
  CONSTRAINT runbook_six_parts CHECK (
    jsonb_typeof(parts) = 'object' AND (parts - 'sees' - 'may' - 'never' - 'escalate' - 'say' - 'clock') = '{}'::jsonb
    AND parts ?& ARRAY['sees','may','never','escalate','say','clock']
    AND jsonb_typeof(parts->'sees') = 'string' AND jsonb_typeof(parts->'may') = 'string' AND jsonb_typeof(parts->'never') = 'string'
    AND jsonb_typeof(parts->'escalate') = 'string' AND jsonb_typeof(parts->'say') = 'string' AND jsonb_typeof(parts->'clock') = 'string'
    AND length(parts->>'sees') > 2 AND length(parts->>'may') > 2 AND length(parts->>'never') > 2 AND length(parts->>'escalate') > 2 AND length(parts->>'say') > 2 AND length(parts->>'clock') > 2),
  -- part 3 always carries the fixed no-promise line
  CONSTRAINT runbook_never_line CHECK (position('Never promise a date, a refund, a credit, an upgrade or an owner decision.' in parts->>'never') > 0),  -- no-money-gate-ok
  -- R9: 1..12 short steps
  CONSTRAINT runbook_steps CHECK (jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) BETWEEN 1 AND 12),
  -- R7: no promise words in what the employee says (part 5 and the say-text)
  CONSTRAINT runbook_say_clean CHECK (desk.fadm_runbook_clean(say_text) AND desk.fadm_runbook_clean(parts->>'say'))
);
CREATE INDEX IF NOT EXISTS fadm_runbook_version_key_i ON desk.fadm_runbook_version (runbook_key, id DESC);

-- R3: the chain (computed here, the app cannot choose it) + the number must rise + rows are frozen
CREATE OR REPLACE FUNCTION desk.fadm_runbook_version_chain() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, desk AS $f$
DECLARE p bytea; lastv integer[];
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('desk.fadm_runbook_version'));
  SELECT ARRAY[major,minor,patch] INTO lastv FROM desk.fadm_runbook_version WHERE runbook_key = NEW.runbook_key ORDER BY major DESC, minor DESC, patch DESC LIMIT 1;
  IF lastv IS NOT NULL AND ARRAY[NEW.major,NEW.minor,NEW.patch] <= lastv THEN RAISE EXCEPTION 'a runbook version number must rise (% -> %.%.%)', lastv, NEW.major, NEW.minor, NEW.patch USING ERRCODE = 'check_violation'; END IF;
  SELECT hash INTO p FROM desk.fadm_runbook_version ORDER BY id DESC LIMIT 1;
  IF p IS NULL THEN p := sha256('anexomail-desk-runbook-genesis'::bytea); END IF;
  NEW.created_at := now(); NEW.prev_hash := p;
  NEW.hash := sha256(p || convert_to(NEW.runbook_key || '|' || NEW.major || '.' || NEW.minor || '.' || NEW.patch || '|' || NEW.parts::text || '|' || NEW.steps::text || '|' || NEW.say_text || '|' || NEW.changelog || '|' || NEW.created_at::text, 'UTF8'));
  RETURN NEW;
END $f$;
CREATE OR REPLACE FUNCTION desk.fadm_runbook_frozen() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $f$
BEGIN RAISE EXCEPTION '% is append-only (% refused)', TG_TABLE_NAME, TG_OP USING ERRCODE = 'insufficient_privilege'; END $f$;
DROP TRIGGER IF EXISTS fadm_runbook_version_chain ON desk.fadm_runbook_version;
CREATE TRIGGER fadm_runbook_version_chain BEFORE INSERT ON desk.fadm_runbook_version FOR EACH ROW EXECUTE FUNCTION desk.fadm_runbook_version_chain();
DROP TRIGGER IF EXISTS fadm_runbook_version_frozen ON desk.fadm_runbook_version;
CREATE TRIGGER fadm_runbook_version_frozen BEFORE UPDATE OR DELETE ON desk.fadm_runbook_version FOR EACH ROW EXECUTE FUNCTION desk.fadm_runbook_frozen();
DROP TRIGGER IF EXISTS fadm_runbook_version_frozen_t ON desk.fadm_runbook_version;
CREATE TRIGGER fadm_runbook_version_frozen_t BEFORE TRUNCATE ON desk.fadm_runbook_version FOR EACH STATEMENT EXECUTE FUNCTION desk.fadm_runbook_frozen();

-- R2 + R5: approval and validation are separate append-only EVENTS; only an active owner (role 'owner') can be the actor
CREATE TABLE IF NOT EXISTS desk.fadm_runbook_event (
  id         bigserial PRIMARY KEY,
  version_id bigint NOT NULL REFERENCES desk.fadm_runbook_version(id),
  kind       text   NOT NULL CHECK (kind IN ('approved','validated')),
  actor      uuid   NOT NULL REFERENCES desk.fadm_owner(id),
  at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS fadm_runbook_event_v_i ON desk.fadm_runbook_event (version_id, kind, at DESC);
CREATE OR REPLACE FUNCTION desk.fadm_runbook_event_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, desk AS $f$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM desk.fadm_owner WHERE id = NEW.actor AND role = 'owner' AND active) THEN RAISE EXCEPTION 'only an active owner can approve or validate a runbook' USING ERRCODE = 'insufficient_privilege'; END IF;
  NEW.at := now(); RETURN NEW;
END $f$;
DROP TRIGGER IF EXISTS fadm_runbook_event_guard ON desk.fadm_runbook_event;
CREATE TRIGGER fadm_runbook_event_guard BEFORE INSERT ON desk.fadm_runbook_event FOR EACH ROW EXECUTE FUNCTION desk.fadm_runbook_event_guard();
DROP TRIGGER IF EXISTS fadm_runbook_event_frozen ON desk.fadm_runbook_event;
CREATE TRIGGER fadm_runbook_event_frozen BEFORE UPDATE OR DELETE ON desk.fadm_runbook_event FOR EACH ROW EXECUTE FUNCTION desk.fadm_runbook_frozen();
DROP TRIGGER IF EXISTS fadm_runbook_event_frozen_t ON desk.fadm_runbook_event;
CREATE TRIGGER fadm_runbook_event_frozen_t BEFORE TRUNCATE ON desk.fadm_runbook_event FOR EACH STATEMENT EXECUTE FUNCTION desk.fadm_runbook_frozen();

-- forced RLS, no right for desk_app on any table (the doors below are the only way), one installer policy as in AD1
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['fadm_runbook','fadm_runbook_version','fadm_runbook_event'] LOOP
    EXECUTE format('ALTER TABLE desk.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE desk.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON desk.%I FROM PUBLIC', t); EXECUTE format('REVOKE ALL ON desk.%I FROM desk_app', t);
    EXECUTE format('DROP POLICY IF EXISTS p_installer ON desk.%I', t); EXECUTE format('CREATE POLICY p_installer ON desk.%I FOR ALL TO %I USING (true) WITH CHECK (true)', t, current_user);
  END LOOP;
END $$;
REVOKE ALL ON SEQUENCE desk.fadm_runbook_version_id_seq, desk.fadm_runbook_event_id_seq FROM PUBLIC;

-- 3) the doors ---------------------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION desk.fadm_runbook_staff(p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, desk AS $f$
  SELECT EXISTS (SELECT 1 FROM desk.fadm_owner WHERE id = p_owner AND active) $f$;
-- the library: the current version of every runbook, with approval, validation and the 90-day stale flag (R4, R5)
CREATE OR REPLACE FUNCTION desk.fadm_runbooks_list(p_owner uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, desk AS $f$
BEGIN
  IF NOT desk.fadm_runbook_staff(p_owner) THEN RETURN NULL; END IF;
  RETURN COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'sort')::int) FROM (
    SELECT jsonb_build_object('key', r.key, 'sort', r.sort, 'title', r.title, 'version_id', v.id, 'version', v.major || '.' || v.minor || '.' || v.patch,
      'parts', v.parts, 'steps', v.steps, 'say_text', v.say_text, 'changelog', v.changelog, 'updated_at', v.created_at,
      'approved_at', (SELECT max(e.at) FROM desk.fadm_runbook_event e WHERE e.version_id = v.id AND e.kind = 'approved'),
      'validated_at', (SELECT max(e.at) FROM desk.fadm_runbook_event e JOIN desk.fadm_runbook_version vv ON vv.id = e.version_id WHERE vv.runbook_key = r.key AND e.kind = 'validated'),
      'stale', COALESCE((SELECT max(e.at) FROM desk.fadm_runbook_event e JOIN desk.fadm_runbook_version vv ON vv.id = e.version_id WHERE vv.runbook_key = r.key AND e.kind = 'validated'), '-infinity'::timestamptz) < now() - interval '90 days') AS x
    FROM desk.fadm_runbook r JOIN LATERAL (SELECT * FROM desk.fadm_runbook_version WHERE runbook_key = r.key ORDER BY major DESC, minor DESC, patch DESC LIMIT 1) v ON true) q), '[]'::jsonb);
END $f$;
-- add a version (owner only; the CHECKs and the chain do the rest)
CREATE OR REPLACE FUNCTION desk.fadm_runbook_add_version(p_owner uuid, p_key text, p_major int, p_minor int, p_patch int, p_parts jsonb, p_steps jsonb, p_say text, p_changelog text) RETURNS bigint LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, desk AS $f$
DECLARE new_id bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM desk.fadm_owner WHERE id = p_owner AND role = 'owner' AND active) THEN RETURN NULL; END IF;
  INSERT INTO desk.fadm_runbook_version (runbook_key, major, minor, patch, parts, steps, say_text, changelog, changed_by) VALUES (p_key, p_major, p_minor, p_patch, p_parts, p_steps, p_say, p_changelog, p_owner) RETURNING desk.fadm_runbook_version.id INTO new_id;
  INSERT INTO desk.fadm_ledger (actor, kind, detail) VALUES (p_owner, 'runbook.version_added', jsonb_build_object('key', p_key, 'version', p_major || '.' || p_minor || '.' || p_patch));
  RETURN new_id;
END $f$;
CREATE OR REPLACE FUNCTION desk.fadm_runbook_mark(p_owner uuid, p_version_id bigint, p_kind text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, desk AS $f$
DECLARE k text; ver text;
BEGIN
  IF p_kind NOT IN ('approved','validated') THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM desk.fadm_owner WHERE id = p_owner AND role = 'owner' AND active) THEN RETURN false; END IF;
  SELECT runbook_key, major || '.' || minor || '.' || patch INTO k, ver FROM desk.fadm_runbook_version WHERE id = p_version_id; IF k IS NULL THEN RETURN false; END IF;
  -- only the CURRENT version of a runbook can be approved or validated (an old version is history)
  IF p_version_id <> (SELECT id FROM desk.fadm_runbook_version WHERE runbook_key = k ORDER BY major DESC, minor DESC, patch DESC LIMIT 1) THEN RETURN false; END IF;
  INSERT INTO desk.fadm_runbook_event (version_id, kind, actor) VALUES (p_version_id, p_kind, p_owner);
  INSERT INTO desk.fadm_ledger (actor, kind, detail) VALUES (p_owner, CASE p_kind WHEN 'approved' THEN 'runbook.approved' ELSE 'runbook.validated' END, jsonb_build_object('key', k, 'version', ver));
  RETURN true;
END $f$;
-- verify the version chain from the first row (for the Bridge and the audit proof)
CREATE OR REPLACE FUNCTION desk.fadm_runbook_chain_verify() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, desk AS $f$
DECLARE r record; p bytea := sha256('anexomail-desk-runbook-genesis'::bytea);
BEGIN
  FOR r IN SELECT * FROM desk.fadm_runbook_version ORDER BY id LOOP
    IF r.prev_hash <> p THEN RETURN false; END IF;
    IF r.hash <> sha256(p || convert_to(r.runbook_key || '|' || r.major || '.' || r.minor || '.' || r.patch || '|' || r.parts::text || '|' || r.steps::text || '|' || r.say_text || '|' || r.changelog || '|' || r.created_at::text, 'UTF8')) THEN RETURN false; END IF;
    p := r.hash;
  END LOOP;
  RETURN true;
END $f$;
REVOKE ALL ON FUNCTION desk.fadm_runbook_clean(text) FROM PUBLIC;   -- found by the AD2 and AD3 CHECKS on the server: no Desk function may be executable by PUBLIC (only the doors, granted to desk_app)
REVOKE ALL ON FUNCTION desk.fadm_runbook_staff(uuid), desk.fadm_runbooks_list(uuid), desk.fadm_runbook_add_version(uuid,text,int,int,int,jsonb,jsonb,text,text), desk.fadm_runbook_mark(uuid,bigint,text), desk.fadm_runbook_chain_verify() FROM PUBLIC;
REVOKE ALL ON FUNCTION desk.fadm_runbook_staff(uuid) FROM desk_app;   -- internal helper
REVOKE ALL ON FUNCTION desk.fadm_runbook_version_chain(), desk.fadm_runbook_frozen(), desk.fadm_runbook_event_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION desk.fadm_runbooks_list(uuid), desk.fadm_runbook_add_version(uuid,text,int,int,int,jsonb,jsonb,text,text), desk.fadm_runbook_mark(uuid,bigint,text), desk.fadm_runbook_chain_verify() TO desk_app;

