-- 5) SELFTEST (rolls back; success is the exception P0AH9) ---------------------------------------------------------------------------------------------------
DO $t$
DECLARE ow uuid; ag uuid; vid bigint; bad text; ok boolean; n int; nx int;
  good_parts jsonb := jsonb_build_object('sees','a b c','may','a b c','never','a b c. Never promise a date, a refund, a credit, an upgrade or an owner decision.','escalate','a b c','say','I can see it','clock','plan target');  -- no-money-gate-ok
BEGIN
  INSERT INTO desk.fadm_owner (email, display_name, role, pw_hash) VALUES ('ad9-selftest-owner@example.test','AD9 owner','owner','$argon2id$selftest') RETURNING id INTO ow;
  INSERT INTO desk.fadm_owner (email, display_name, role, pw_hash, passkey_required, status, active) VALUES ('ad9-selftest-agent@example.test','AD9 agent','agent',NULL,true,'active',true) RETURNING id INTO ag;
  SELECT COALESCE(max(major), 0) + 1 INTO nx FROM desk.fadm_runbook_version WHERE runbook_key = 'R1';   -- the selftest works on top of whatever versions already exist
  IF (SELECT count(*) FROM desk.fadm_runbook) < 9 THEN RAISE EXCEPTION 'AD9 selftest: fewer than nine runbooks'; END IF;
  IF jsonb_array_length(desk.fadm_runbooks_list(ag)) < 9 THEN RAISE EXCEPTION 'AD9 selftest: staff cannot read the library'; END IF;
  IF desk.fadm_runbooks_list(gen_random_uuid()) IS NOT NULL THEN RAISE EXCEPTION 'AD9 selftest: a stranger read the library'; END IF;
  -- R7: every banned word and the whitelist
  FOREACH bad IN ARRAY ARRAY['I promise this','a guarantee','It will be fixed soon. This will be fixed.','a refund','a credit','compensation','a discount','it is free','within 2 hours','I will make sure','100 percent','for sure','definitely'] LOOP  -- no-money-gate-ok
    IF desk.fadm_runbook_clean(bad) IS NOT FALSE THEN RAISE EXCEPTION 'AD9 selftest: banned text passed: %', bad; END IF;
  END LOOP;
  IF desk.fadm_runbook_clean('Our published billing policy says payments are not refunded or credited once the service has been used. You can read it on the Billing Policy page.') IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: the policy sentence is not whitelisted'; END IF;  -- no-money-gate-ok
  IF desk.fadm_runbook_clean('I can see your account. The next update is due by the plan target.') IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: a clean sentence failed'; END IF;
  -- agent cannot add, approve or validate; owner can
  IF desk.fadm_runbook_add_version(ag,'R1',nx,0,0,good_parts,'["one step"]'::jsonb,'I can see it clearly','a try') IS NOT NULL THEN RAISE EXCEPTION 'AD9 selftest: an agent added a version'; END IF;
  vid := desk.fadm_runbook_add_version(ow,'R1',nx,0,0,good_parts,'["one step"]'::jsonb,'I can see it clearly','AD9 selftest version');
  IF vid IS NULL THEN RAISE EXCEPTION 'AD9 selftest: the owner could not add a version'; END IF;
  IF desk.fadm_runbook_mark(ag, vid, 'approved') IS NOT FALSE THEN RAISE EXCEPTION 'AD9 selftest: an agent approved'; END IF;
  IF desk.fadm_runbook_mark(ow, vid, 'approved') IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: the owner could not approve'; END IF;
  IF desk.fadm_runbook_mark(ow, (SELECT min(id) FROM desk.fadm_runbook_version WHERE runbook_key='R1'), 'approved') IS NOT FALSE THEN RAISE EXCEPTION 'AD9 selftest: an old version was approved'; END IF;
  IF desk.fadm_runbook_mark(ow, vid, 'validated') IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: validate failed'; END IF;
  IF (SELECT (x->>'stale')::boolean FROM jsonb_array_elements(desk.fadm_runbooks_list(ow)) x WHERE x->>'key'='R1') IS NOT FALSE THEN RAISE EXCEPTION 'AD9 selftest: a just-validated runbook is stale'; END IF;
  IF (SELECT (x->>'stale')::boolean FROM jsonb_array_elements(desk.fadm_runbooks_list(ow)) x WHERE x->>'key'='R2') IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: a never-validated runbook is not stale'; END IF;
  -- the version number must rise, rows are frozen, the shape CHECKs hold
  BEGIN PERFORM desk.fadm_runbook_add_version(ow,'R1',nx,0,0,good_parts,'["s"]'::jsonb,'I can see it clearly','same number'); RAISE EXCEPTION 'AD9 selftest: a same version number was accepted'; EXCEPTION WHEN unique_violation OR check_violation THEN NULL; END;
  BEGIN UPDATE desk.fadm_runbook_version SET say_text = 'I can see something else' WHERE id = vid; RAISE EXCEPTION 'AD9 selftest: a version was edited'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN DELETE FROM desk.fadm_runbook_event; RAISE EXCEPTION 'AD9 selftest: events deleted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM desk.fadm_runbook_add_version(ow,'R1',nx,1,0,good_parts - 'clock','["s"]'::jsonb,'I can see it clearly','five parts'); RAISE EXCEPTION 'AD9 selftest: five parts accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN PERFORM desk.fadm_runbook_add_version(ow,'R1',nx,1,0,jsonb_set(good_parts,'{never}','"no line here"'),'["s"]'::jsonb,'I can see it clearly','no never line'); RAISE EXCEPTION 'AD9 selftest: part 3 without the fixed line accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN PERFORM desk.fadm_runbook_add_version(ow,'R1',nx,1,0,good_parts,'["s"]'::jsonb,'I promise it works','promise word'); RAISE EXCEPTION 'AD9 selftest: a promise word accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN INSERT INTO desk.fadm_runbook_event (version_id, kind, actor) VALUES (vid, 'approved', ag); RAISE EXCEPTION 'AD9 selftest: agent event accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  IF desk.fadm_runbook_chain_verify() IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: version chain broken'; END IF;
  IF desk.fadm_ledger_verify() IS NOT TRUE THEN RAISE EXCEPTION 'AD9 selftest: ledger chain broken'; END IF;
  RAISE EXCEPTION 'AD9 selftest passed' USING ERRCODE = 'P0AH9';
EXCEPTION WHEN SQLSTATE 'P0AH9' THEN NULL;
END $t$;
COMMIT;
